const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 800, height: 600 },
    deviceScaleFactor: 2,
  });
  const page = await context.newPage();

  const htmlPath = path.resolve('/app/output/poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle' });

  // Wait for AntV Infographic renders to complete
  await page.waitForTimeout(3000);

  // Wait for any SVG elements to appear (indicating infographics rendered)
  await page.waitForSelector('svg', { timeout: 15000 }).catch(() => {
    console.log('No SVG found, proceeding anyway');
  });

  // Extra wait for fonts + final paint
  await page.waitForTimeout(2000);

  // Take full page screenshot
  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: true,
    type: 'png',
  });

  console.log('Poster saved to /app/output/final_poster.png');
  await browser.close();
})();

